def cases():
    return json.loads(json.dumps(CASES))

def finite_records(row):
    return [(float(t),float(y),a) for t,y,a in row['parameters']['records'] if t is not None and y is not None and math.isfinite(float(t)) and math.isfinite(float(y)) and a is not None]

def mathematical(row):
    records=finite_records(row);subjects=list(dict.fromkeys(a for t,y,a in records));p=row['parameters']['period']
    with mp.workdps(80):
        coefs=[]
        for subject in subjects:
            data=[(mp.mpf(str(t)),mp.mpf(str(y))) for t,y,a in records if a==subject]
            if len(data)<4:continue
            X=mp.matrix([[1,mp.cos(2*mp.pi*t/p),mp.sin(2*mp.pi*t/p)] for t,y in data]);y=mp.matrix([v for t,v in data])
            try:coef=mp.lu_solve(X.T*X,X.T*y)
            except (ValueError,ZeroDivisionError):continue
            coefs.append([mp.mpf(0) if abs(v)<mp.mpf('1e-60') else v for v in coef])
        m=len(coefs)
        if m<2:raise ValueError('Need at least two identifiable subject rhythms.')
        M,b,g=[sum(c[i] for c in coefs)/m for i in range(3)]
        amp=mp.sqrt(b*b+g*g);phase=(mp.atan2(g,b)%(2*mp.pi))*p/(2*mp.pi) if amp else mp.nan
        S=mp.matrix([[sum((c[i+1]-[b,g][i])*(c[j+1]-[b,g][j]) for c in coefs)/(m-1) for j in range(2)] for i in range(2)])
        probability=mp.nan
        if m>2 and mp.det(S)>mp.mpf('1e-60'):
            bg=mp.matrix([b,g]);T2=m*(bg.T*S**-1*bg)[0];F=(m-2)*T2/(2*(m-1))
            probability=mp.betainc(mp.mpf(m-2)/2,1,0,(m-2)/((m-2)+2*F),regularized=True)
        se=mp.sqrt(max((b*b*S[0,0]+2*b*g*S[0,1]+g*g*S[1,1])/(m*amp**2),mp.mpf(0))) if amp else mp.nan
        return [float(v) for v in [M,amp,phase,p,mp.nan,probability,se,mp.nan,m]]

def source_setup():
    source=SOURCE.read_text(encoding='utf-8')
    # Load unchanged definitions; dependencies of unused functions are not invoked.
    chunks=[source[i:i+3000] for i in range(0,len(source),3000)]
    return 'eval(parse(text=paste0('+','.join(json.dumps(c) for c in chunks)+')),envir=.GlobalEnv);1'

def native_query(row):
    data=finite_records(row);subjects=list(dict.fromkeys(a for t,y,a in data));p=row['parameters']['period']
    vector=lambda xs:'c('+','.join(format(v,'.17g') for v in xs)+')'
    source=SOURCE.read_text(encoding='utf-8');start=source.index('  sdm<-(sd(popmat[1,]))');end=source.index('  t<-abs(qt(alpha/2',start)
    unchanged_covariance=source[start:end]
    return f'''local({{
        t<-{vector([t for t,y,a in data])};y<-{vector([y for t,y,a in data])};subject<-{vector([subjects.index(a) for t,y,a in data])};
        popmat<-sapply(unique(subject),function(a){{
            keep<-subject==a;if(sum(keep)<4)return(rep(NA_real_,3));
            lm.fit(cbind(1,cos(2*pi*t[keep]/{p}),sin(2*pi*t[keep]/{p})),y[keep])$coefficients
        }});popmat<-popmat[,apply(popmat,2,function(v)all(is.finite(v))),drop=FALSE];
        popmat<-as.data.frame(popmat);coefs<-rowMeans(popmat);MESOR<-coefs[1];beta<-coefs[2];gamma<-coefs[3];amplitude<-sqrt(beta^2+gamma^2);
        {unchanged_covariance}
        obj<-list(pop.mat=as.data.frame(popmat));class(obj)<-'population.cosinor.lm';
        probability<-if(k>2 && abs(det(cov(t(as.matrix(popmat[2:3,,drop=FALSE])))))>1e-25) cosinor.detect(obj)[1,4] else NA_real_;
        phase<-(atan2(gamma,beta)%%(2*pi))*{p}/(2*pi);
        c(MESOR,amplitude,phase,{p},NA_real_,probability,sqrt(c22),NA_real_,k)
    }})'''

def production(row):
    import pandas as pd
    from PyFLASH.stats_extra import _population_mean_cosinor
    data=pd.DataFrame(finite_records(row),columns=['_t','_v','animal'])
    answer=_population_mean_cosinor(data,'animal',row['parameters']['period'],False)
    assert set(answer)==set(FIELDS)
    return [answer[k] for k in FIELDS]

def check_identity():
    fixture=json.loads(FIXTURE.read_text(encoding='utf-8'))
    if hashlib.sha256(Path(__file__).read_text(encoding='utf-8').encode()).hexdigest()!=fixture['reference_code_sha256']:
        raise ValueError('Frozen population-rhythm reference code changed.')
    if hashlib.sha256(SOURCE.read_bytes()).hexdigest()!=fixture['published_source_sha256']:
        raise ValueError('Published population-rhythm reference source changed.')
    current=cases()
    if current!=[{k:r[k] for k in c} for c,r in zip(current,fixture['rows'],strict=True)]:
        raise ValueError('Frozen population-rhythm input definitions changed.')
    queries=[{'key':'published-source-setup','code':source_setup()},*[{'key':r['key'],'code':native_query(r)} for r in current]]
    if queries!=[{k:r[k] for k in q} for q,r in zip(queries,fixture['native']['rows'],strict=True)]:
        raise ValueError('Frozen native population-rhythm expressions changed.')
    return fixture,queries

def execute(output):
    fixture,queries=check_identity()
    result=execute_queries(queries,output,name='population-rhythm-published-branch')
    for key in ['R','webR','wasm_sha256']:
        if result[key]!=fixture['native'][key]:raise ValueError('Native population-rhythm runtime changed: '+key)
    return result
